import json, pathlib
P=pathlib.Path(__file__).resolve().parent.parent

def write(name,obj):
 p=P/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
subjects=[('mathematics','Engineering Mathematics','sigma',['Linear Algebra','Calculus','Differential Equations','Complex Analysis','Probability and Statistics']),('networks','Networks, Signals and Systems','activity',['Circuit Analysis','Network Theorems','Transient Analysis','Laplace Transform','Fourier Transform','Signals and Systems','LTI Systems','Sampling']),('devices','Electronic Devices','cpu',['Semiconductor Physics','Carrier Transport','PN Junctions','Diodes','BJT','MOSFET']),('analog','Analog Circuits','audio-lines',['Diode Circuits','Amplifiers','Operational Amplifiers','Feedback','Oscillators']),('digital','Digital Circuits','binary',['Boolean Algebra','Logic Gates','Karnaugh Maps','Combinational Circuits','Sequential Circuits','Flip-Flops','Data Converters']),('control','Control Systems','sliders-horizontal',['Transfer Functions','Time Response','Stability','Root Locus','Frequency Response','State-Space Analysis']),('communications','Communications','radio',['Analog Communication','Digital Communication','Modulation','Information Theory','Noise','Probability of Error']),('electromagnetics','Electromagnetics','waves',['Maxwell Equations','Electromagnetic Waves','Transmission Lines','Wave Propagation','Antennas']),('aptitude','General Aptitude','brain',['Verbal Aptitude','Quantitative Aptitude','Analytical Aptitude','Spatial Aptitude'])]
